//! Platform clipboard change stamp.
//!
//! A single cheap syscall answers "did the clipboard change at all"; only then
//! is the content actually read, so a polling cycle never blindly reads large
//! content such as images:
//! - macOS: `NSPasteboard.changeCount` (increments on every clipboard write)
//! - Windows: `GetClipboardSequenceNumber` (no need to open the clipboard)
//! - Linux: no uniform cheap stamp, returns None, and the layer above falls
//!   back to reading text and comparing

/// Whether this platform provides a cheap change stamp
pub fn supported() -> bool {
    cfg!(any(target_os = "macos", windows))
}

/// Read the current change stamp; always None on platforms without one
#[cfg(target_os = "macos")]
pub fn read() -> Option<i64> {
    // Safe binding generated by objc2: NSPasteboard is accessible from any
    // thread
    let pasteboard = objc2_app_kit::NSPasteboard::generalPasteboard();
    Some(pasteboard.changeCount() as i64)
}

/// Read the current change stamp; always None on platforms without one
#[cfg(windows)]
#[expect(
    unsafe_code,
    reason = "GetClipboardSequenceNumber 为纯读取系统调用, 无指针与内存安全影响"
)]
pub fn read() -> Option<i64> {
    let seq = unsafe { windows_sys::Win32::System::DataExchange::GetClipboardSequenceNumber() };
    Some(i64::from(seq))
}

/// Read the current change stamp; always None on platforms without one
#[cfg(not(any(target_os = "macos", windows)))]
pub fn read() -> Option<i64> {
    None
}
